#include "Cpu.h"
#include "flexTimer_pwm1.h"
#include "ftm.h"

static ftm_state_t ftm0State;
static uint16_t led6DutyCycle;
static bool led6BreathIncreasing;
static uint32_t led6BreathUpdateCounter;

#define LED6_BREATH_STEP (0x0100U)
#define LED6_BREATH_UPDATE_DIVIDER (10000U)

void Ftm0_Led6PwmInit(void)
{
    /* Initialize FTM0 and start the generated PWM configuration for LED6. */
    (void)FTM_DRV_Init(
        INST_FLEXTIMER_PWM1,
        &flexTimer_pwm1_InitConfig,
        &ftm0State);
    /* Keep the duty cycle generated by Processor Expert as the initial value. */
    led6DutyCycle =
        flexTimer_pwm1_IndependentChannelsConfig[0U].uDutyCyclePercent;
    led6BreathIncreasing = true;
    led6BreathUpdateCounter = 0U;
    (void)FTM_DRV_InitPwm(
        INST_FLEXTIMER_PWM1,
        &flexTimer_pwm1_PwmConfig);
}


// Ftm0_Led6PwmSetDuty(0x2000U); // 20%
// Ftm0_Led6PwmSetDuty(0x4000U); // 50%
// Ftm0_Led6PwmSetDuty(0x6000U); // 75%
// Ftm0_Led6PwmSetDuty(0x8000U); // 100%
  //调用(void)Ftm0_Led6PwmSetDuty(0x1000U);
status_t Ftm0_Led6PwmSetDuty(uint16_t dutyCycle)
{
    status_t status;

    if (dutyCycle > FTM_MAX_DUTY_CYCLE) {
        return STATUS_ERROR;
    }

    status = FTM_DRV_UpdatePwmChannel(
        INST_FLEXTIMER_PWM1,
        0U,
        FTM_PWM_UPDATE_IN_DUTY_CYCLE,
        dutyCycle,
        0U,
        true);

    if (status == STATUS_SUCCESS) {
        led6DutyCycle = dutyCycle;
    }

    return status;
}

uint16_t Ftm0_Led6PwmGetDuty(void)
{
    return led6DutyCycle;
}

void Ftm0_Led6PwmBreathProcess(void)
{
    uint32_t nextDutyCycle;

    ++led6BreathUpdateCounter;
    if (led6BreathUpdateCounter < LED6_BREATH_UPDATE_DIVIDER) {
        return;
    }
    led6BreathUpdateCounter = 0U;

    if (led6BreathIncreasing) {
        nextDutyCycle = (uint32_t)led6DutyCycle + LED6_BREATH_STEP;
        if (nextDutyCycle >= FTM_MAX_DUTY_CYCLE) {
            nextDutyCycle = FTM_MAX_DUTY_CYCLE;
            led6BreathIncreasing = false;
        }
    } else if (led6DutyCycle <= LED6_BREATH_STEP) {
        nextDutyCycle = 0U;
        led6BreathIncreasing = true;
    } else {
        nextDutyCycle = (uint32_t)led6DutyCycle - LED6_BREATH_STEP;
    }

    (void)Ftm0_Led6PwmSetDuty((uint16_t)nextDutyCycle);
}
